package org.aibles.ecommerce.devbox_portal.service;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ServiceSettingsTest {

    private static final String FILE = """
            # order-service in preview-ui — generated by `make devbox-env-create` from envs/prod-like.
            # Edit freely and commit: this file is now the truth for preview-ui.
            apps:
              order-service:
                image:
                  tag: 7407ad0
                hpa: null
                resources:
                  requests:
                    cpu: 50m
            """;

    @Test
    void aMapKeyWithDotsSurvivesTheRoundTripInBracketNotation() {
        // The Kafka group-id trap: split on the dots, this would bind a look-alike key.
        Map<String, Object> nested = Map.of("application", Map.of("kafka", Map.of("group-id",
                Map.of("payment.success", "preview-ui.payment-success-group"))));

        Map<String, String> flat = ServiceSettings.flatten(nested);
        assertThat(flat).containsExactly(Map.entry(
                "application.kafka.group-id[payment.success]", "preview-ui.payment-success-group"));
        assertThat(ServiceSettings.unflatten(flat)).isEqualTo(nested);
    }

    @Test
    void savingSettingsKeepsTheTagTheRestOfTheFileAndItsHeader() {
        String out = ServiceSettings.withSettings(FILE, "order-service",
                Map.of("logging.level.org.aibles", "DEBUG"), Map.of("JAVA_TOOL_OPTIONS", "-Xss512k"));

        assertThat(out).startsWith("# order-service in preview-ui");
        Map<String, Map<String, String>> back = ServiceSettings.read(out, "order-service");
        assertThat(back.get("spring")).containsExactly(Map.entry("logging.level.org.aibles", "DEBUG"));
        assertThat(back.get("env")).containsExactly(Map.entry("JAVA_TOOL_OPTIONS", "-Xss512k"));
        assertThat(out).contains("tag: 7407ad0").contains("hpa: null").contains("cpu: 50m");
    }

    @Test
    void emptySettingsRemoveTheBlocksInsteadOfLeavingEmptyMaps() {
        String with = ServiceSettings.withSettings(FILE, "order-service", Map.of("a.b", "1"), Map.of("X", "y"));
        String without = ServiceSettings.withSettings(with, "order-service", Map.of(), Map.of());

        assertThat(without).doesNotContain("springConfig").doesNotContain("env:");
        assertThat(without).contains("tag: 7407ad0");
    }

    @Test
    void secretsAreRefusedByNameOrShape() {
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of("spring.datasource.password", "x"), Map.of()))
                .hasMessageContaining("Vault");
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of(), Map.of("PAYPAL_CLIENT_SECRET", "x")))
                .hasMessageContaining("Vault");
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of("x.header", "eyJhbGciOiJSUzI1NiJ9.e30.sig"), Map.of()))
                .hasMessageContaining("secret");
    }

    @Test
    void theChartOwnedEnvVarAndBadNamesAreRefused() {
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of(), Map.of("SPRING_APPLICATION_JSON", "{}")))
                .hasMessageContaining("generated");
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of(), Map.of("1BAD", "x")))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> ServiceSettings.validate(Map.of("bad key", "x"), Map.of()))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void ordinarySettingsPass() {
        ServiceSettings.validate(
                Map.of("logging.level.root", "INFO", "application.kafka.group-id[payment.success]", "g"),
                Map.of("SPRING_PROFILES_ACTIVE", "k8s", "JAVA_TOOL_OPTIONS", "-Xss512k"));
    }

    @Test
    void inheritedDefaultsComeFromEnvYaml() {
        String envYaml = """
                defaults:
                  springConfig:
                    spring:
                      data:
                        redis:
                          host: redis
                """;
        assertThat(ServiceSettings.inheritedSpring(envYaml)).containsEntry("spring.data.redis.host", "redis");
    }
}
